const item = $input.first();
const headers = item.json.headers || {};
let body = item.json.body || item.json || {};
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = {}; }
}
if (body && typeof body.body === 'string') {
  try { body.body = JSON.parse(body.body); } catch (e) {}
}
if (body && typeof body.payload === 'string') {
  const outerSecret = body.secret || '';
  try {
    const parsedPayload = JSON.parse(body.payload);
    if (parsedPayload && typeof parsedPayload === 'object' && !Array.isArray(parsedPayload)) {
      body = { ...parsedPayload, secret: parsedPayload.secret || outerSecret };
    }
  } catch (e) {}
}
if (body && body.body && typeof body.body === 'object' && (body.body.secret || body.body.file_data_uri)) {
  body = body.body;
}
const expectedSecret = $env.STITCHSENSE_UPLOAD_SECRET || 'uigfbwejbCHNRwjrwehrbcvHBWEVENVEKEWVBJWE';
const normalisedHeaders = {};
for (const key of Object.keys(headers)) normalisedHeaders[key.toLowerCase()] = headers[key];
const providedSecret = normalisedHeaders['x-stitchsense-secret'] || body.secret || body.STITCHSENSE_UPLOAD_SECRET || '';
if (expectedSecret && providedSecret !== expectedSecret) {
  return [{ json: { ok:false, statusCode:401, error:'Unauthorised upload request.' } }];
}
return [{ json: { ok:true, body, headers, received_at:new Date().toISOString() }, binary:item.binary }];

const item = $input.first();
let body = item.json.body || item.json || {};
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = {}; }
}
if (body && typeof body.body === 'string') {
  try { body.body = JSON.parse(body.body); } catch (e) {}
}
if (body && typeof body.payload === 'string') {
  const outerSecret = body.secret || '';
  try {
    const parsedPayload = JSON.parse(body.payload);
    if (parsedPayload && typeof parsedPayload === 'object' && !Array.isArray(parsedPayload)) {
      body = { ...parsedPayload, secret: parsedPayload.secret || outerSecret };
    }
  } catch (e) {}
}
if (body && body.body && typeof body.body === 'object' && (body.body.file_data_uri || body.body.file_name)) {
  body = body.body;
}
let binary = item.binary || {};
let uploadKey = Object.keys(binary).includes('file') ? 'file' : Object.keys(binary)[0];

function normaliseDataUri(value) {
  const raw = String(value || '').trim();
  const match = raw.match(/^data:([^;,]+)?(?:;[^,]*)?;base64,(.*)$/i);
  if (!match) return null;
  return { mime: (match[1] || '').toLowerCase(), base64: match[2] || '' };
}

// v7.4.26 accepts JSON/base64 uploads from WordPress/browser as well as legacy multipart.
if (!uploadKey && body.file_data_uri) {
  const parsed = normaliseDataUri(body.file_data_uri);
  if (!parsed || !parsed.base64) {
    return [{ json:{ ok:false, statusCode:400, error:'The uploaded file payload was not readable. Please try uploading the file again.' } }];
  }
  const fileNameFromBody = String(body.file_name || body.filename || 'pattern-upload').trim() || 'pattern-upload';
  const mimeFromBody = String(body.mime_type || body.mimeType || parsed.mime || 'application/octet-stream').toLowerCase();
  binary = {
    file: {
      data: parsed.base64,
      mimeType: mimeFromBody,
      fileName: fileNameFromBody,
      fileSize: Number(body.file_size || body.fileSize || Math.floor(parsed.base64.length * 0.75) || 0)
    }
  };
  uploadKey = 'file';
}

const binaryKeys = Object.keys(binary);
if (!binaryKeys.length || !uploadKey) return [{ json:{ ok:false, statusCode:400, error:'No file uploaded.' } }];
const file = binary[uploadKey];
const mimeType = String(file.mimeType || file.mime_type || body.mime_type || body.mimeType || '').toLowerCase();
const fileName = file.fileName || file.filename || body.file_name || body.filename || 'pattern-upload';
const extMatch = String(fileName).toLowerCase().match(/\.([a-z0-9]+)$/);
const ext = extMatch ? extMatch[1] : '';
const supported = ['pdf','docx','txt','rtf','odt','md','html','htm','epub','csv','xlsx','json','xml','jpg','jpeg','png','webp','gif','tif','tiff'];
if (!supported.includes(ext)) {
  return [{ json:{ ok:false, statusCode:415, error:`Unsupported file type: ${ext || mimeType || fileName}. Please upload PDF, DOCX, TXT, RTF, ODT, MD, HTML, EPUB, CSV, XLSX, JSON, XML, JPG, PNG, WebP, GIF or TIFF.` } }];
}
const size = Number(file.fileSize || file.fileSizeBytes || file.file_size || body.file_size || 0);
const maxSize = 20 * 1024 * 1024;
if (size > maxSize) return [{ json:{ ok:false, statusCode:413, error:'File too large. Maximum upload size is 20MB.' } }];
const directTextExts = ['txt','md','html','htm','json','xml','csv','rtf'];
const imageExts = ['jpg','jpeg','png','webp','gif','tif','tiff'];
const safeName = String(fileName).replace(/[^a-zA-Z0-9._-]/g, '-').slice(0, 160);
const stamp = Date.now();
const projectName = String(body.project_name || body.projectName || safeName.replace(/\.[^.]+$/, '') || 'Untitled project').trim();
return [{ json:{ ok:true, upload_key:uploadKey, original_filename:fileName, stored_filename:`${stamp}-${safeName}`, mime_type:mimeType || 'application/octet-stream', file_extension:ext, is_pdf:ext === 'pdf' || mimeType === 'application/pdf', is_direct_text:directTextExts.includes(ext), is_image:imageExts.includes(ext), file_size:size, project_name:projectName, craft_type:String(body.craft_type || body.craftType || '').trim(), project_type:String(body.project_type || body.projectType || 'uploaded_pattern').trim(), user_email:String(body.email || body.user_email || '').trim(), wp_user_id:body.wp_user_id || body.wpUserId || null, storage_path:`/opt/stitchsense/uploads/${stamp}-${safeName}`, received_at:item.json.received_at || new Date().toISOString() }, binary }];

const validation = $('Validate File').first().json;
const db = $json;
return [{ json: { ...validation, project_id: db.project_id, file_id: db.file_id, job_id: db.job_id }, binary: $('Validate File').first().binary }];

const source = $('Merge DB IDs').first().json;
let raw = '';
try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, source.upload_key);
  raw = buffer.toString('utf8');
} catch (error) {
  const bin = $input.first().binary?.[source.upload_key];
  raw = bin?.data ? Buffer.from(bin.data, 'base64').toString('utf8') : '';
}
const ext = String(source.file_extension || '').toLowerCase();
if (ext === 'json') {
  try { raw = JSON.stringify(JSON.parse(raw), null, 2); } catch (e) {}
}
if (ext === 'html' || ext === 'htm' || ext === 'xml') {
  raw = raw.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
}
if (ext === 'rtf') {
  raw = raw.replace(/\\'[0-9a-fA-F]{2}/g, ' ').replace(/\\[a-zA-Z]+-?\d* ?/g, ' ').replace(/[{}]/g, ' ');
}
return [{ json: { ...source, text: raw }, binary: $input.first().binary }];

const source = $('Merge DB IDs').first().json;
const rawText = $json.text || '';
let cleaned = String(rawText).replace(/\\/g, ' ').replace(/\r/g, ' ').replace(/\t/g, ' ').replace(/[\u0000-\u001F\u007F-\u009F]/g, ' ').replace(/\s+/g, ' ').trim();
if (!cleaned || cleaned.length < 100) throw new Error('No usable pattern text extracted. The file may be image-only, corrupted, password-protected or unsupported by the current extractor.');
const chunkSize = 1500;
const overlap = 200;
const chunks = [];
function hash(str) { let h=0; for (let i=0;i<str.length;i++){ h=((h<<5)-h)+str.charCodeAt(i); h|=0; } return Math.abs(h).toString(16); }
const contentHash = hash(source.project_id + source.file_id + cleaned.slice(0, 500));
const scrapedAt = new Date().toISOString();
for (let i=0; i<cleaned.length; i += (chunkSize - overlap)) {
  const chunk = cleaned.slice(i, i + chunkSize).trim();
  if (chunk.length > 100) chunks.push({ json:{ ...source, chunk_text:chunk, chunk_index:chunks.length, total_chunks_estimate:Math.ceil(cleaned.length / (chunkSize - overlap)), total_chars:cleaned.length, content_hash:contentHash, scraped_at:scrapedAt, pattern_title_guess:source.project_name, extracted_preview:cleaned.slice(0,2500) } });
}
return chunks;

const embedding = $json.embedding;
if (!embedding || !Array.isArray(embedding)) throw new Error(`No embedding returned. Response: ${JSON.stringify($json)}`);
const chunk = $('Clean + Chunk Text').item.json;
function hashToNumber(str){ let h=0; for(let i=0;i<str.length;i++){ h=((h<<5)-h)+str.charCodeAt(i); h|=0;} return Math.abs(h); }
const pointId = hashToNumber(`${chunk.project_id}:${chunk.file_id}:${chunk.chunk_index}`);
return [{ json:{ ...chunk, embedding, point_id:pointId } }];

const items = $input.all();
if (!items.length) return [];
const first = items[0].json;
const preview = String(first.extracted_preview || '').replace(/\s+/g, ' ').trim();
function pick(regex, fallback='') { const match = preview.match(regex); return match ? String(match[1] || match[0]).trim() : fallback; }
function clean(value){ return String(value || '').replace(/\s+/g, ' ').trim(); }
const title = clean(pick(/(?:^|\s)([A-Z][A-Z\s-]{3,40}JUMPER|[A-Z][A-Z\s-]{3,40}CARDIGAN|[A-Z][A-Z\s-]{3,40}SWEATER|[A-Z][A-Z\s-]{3,40}TOP|[A-Z][A-Z\s-]{3,40}SHAWL|[A-Z][A-Z\s-]{3,40}SCARF)/i) || first.title || first.original_filename || 'Uploaded pattern');
const designCode = clean(pick(/\b(DG\s*\d{2,4}-\d{1,3})\b/i));
const yarn = clean(pick(/YARN\s+(.+?)\s+SIZES/i));
const sizes = clean(pick(/SIZES\s+(.+?)\s+NOTE!/i) || pick(/SIZES\s+(.+?)\s+GARMENT MEASUREMENTS/i));
const needles = clean(pick(/SUGGESTED NEEDLES\s+(.+?)\s+GAUGE/i) || pick(/(?:NEEDLES|HOOK)\s+(.+?)\s+(?:GAUGE|TENSION)/i));
const gauge = clean(pick(/(?:GAUGE|TENSION)\s+(.+?)\s+(?:Check your gauge|ABBREVIATIONS|BODY|PATTERN)/i));
const parts=[];
parts.push(`<b>Pattern uploaded and analysed.</b>`);
parts.push(`This looks like <b>${title}${designCode ? ' (' + designCode + ')' : ''}</b>.`);
if (sizes) parts.push(`<b>Sizes:</b> ${sizes}`);
if (yarn) parts.push(`<b>Yarn:</b> ${yarn}`);
if (needles) parts.push(`<b>Needles / hook:</b> ${needles}`);
if (gauge) parts.push(`<b>Gauge / tension:</b> ${gauge}`);
parts.push(`Ask me about sizing, yarn substitution, gauge, stitch counts, abbreviations or any row/round that looks confusing.`);
return [{ json:{ ...first, total_chunks:items.length, pattern_summary_html:parts.join('<br>'), pattern_summary_text:parts.map(p=>p.replace(/<[^>]+>/g,'')).join('\n'), detected_title:title, detected_design_code:designCode } }];
